INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_COMMAGENE','Commagenian Kingdom',-100,-31)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_VERSLUYS_COMMAGENE','secondary scholarship','Versluys, M.J. — Visual Style and Constructing Identity in the Hellenistic World: Nemrud Dag and Commagene under Antiochos I (Cambridge, 2017)','Royal dynastic cult, syncretic pantheon, hierothesion program, and Greco-Iranian theonyms of Commagene')
INSERT INTO _e VALUES
 ('ENT_COMM_PANTHEON','Pantheon of Commagene','collective','Deity collective','Commagene','dynastic cult, syncretism, royal ancestor cult','B','Hub for the syncretic Greco-Iranian dynastic pantheon established by Antiochus I Theos; attested in the Nomos inscriptions and the colossal seated divine statues of the Nemrud Dag hierothesion.'),
 ('ENT_COMM_ZEUS_OROMASDES','Zeus-Oromasdes','deity','Syncretic deity','Commagene','sky sovereignty, supreme god','B','Supreme deity of the Commagenian pantheon, an explicit fusion of Greek Zeus with Iranian Ahura Mazda (Oromasdes); attested in the Nemrud Dag cult inscriptions and colossal statuary of Antiochus I.'),
 ('ENT_COMM_APOLLO_MITHRAS_HELIOS_HERMES','Apollo-Mithras-Helios-Hermes','deity','Syncretic deity','Commagene','sun, light, mediation, messenger','B','Composite solar/mediating deity of Commagene fusing Apollo, Iranian Mithra(s), Helios and Hermes; named in the Nomos inscriptions and depicted among the Nemrud Dag seated colossi.'),
 ('ENT_COMM_ARTAGNES_HERACLES_ARES','Artagnes-Heracles-Ares','deity','Syncretic deity','Commagene','war, victory, heroic strength','B','Composite warrior deity of Commagene fusing Iranian Verethragna (Artagnes) with Greek Heracles and Ares; attested at Nemrud Dag and in the dexiosis reliefs where Antiochus I clasps his hand.'),
 ('ENT_COMM_TYCHE','Tyche of Commagene','deity','Goddess/personification','Commagene','fortune, territorial personification','B','Personified fortune of the kingdom of Commagene, seated among the divine colossi at Nemrud Dag as the patroness of the land; a regional cult form of Greek Tyche.'),
 ('ENT_COMM_ANTIOCHUS_I_THEOS','Antiochus I Theos of Commagene','deity','Deified human','Commagene','deified king, dynastic ancestor cult','B','King of Commagene (r. c.70-31 BCE) who established and was deified within the royal pantheon; enthroned among the gods at Nemrud Dag and shown in dexiosis with each deity. A deified historical mortal.');
