INSERT INTO entity_sources (entity_id,source_id,evidence_type,source_note)
INSERT INTO _p VALUES
 ('ENT_COMM_PANTHEON','PER_COMMAGENE','Hub for the syncretic Greco-Iranian dynastic pantheon established by Antiochus I Theos; attested in the Nomos inscriptions and the colossal seated divine statues of the Nemrud Dag hierothesion.'),
 ('ENT_COMM_ZEUS_OROMASDES','PER_COMMAGENE','Supreme deity of the Commagenian pantheon, an explicit fusion of Greek Zeus with Iranian Ahura Mazda (Oromasdes); attested in the Nemrud Dag cult inscriptions and colossal statuary of Antiochus I.'),
 ('ENT_COMM_APOLLO_MITHRAS_HELIOS_HERMES','PER_COMMAGENE','Composite solar/mediating deity of Commagene fusing Apollo, Iranian Mithra(s), Helios and Hermes; named in the Nomos inscriptions and depicted among the Nemrud Dag seated colossi.'),
 ('ENT_COMM_ARTAGNES_HERACLES_ARES','PER_COMMAGENE','Composite warrior deity of Commagene fusing Iranian Verethragna (Artagnes) with Greek Heracles and Ares; attested at Nemrud Dag and in the dexiosis reliefs where Antiochus I clasps his hand.'),
 ('ENT_COMM_TYCHE','PER_COMMAGENE','Personified fortune of the kingdom of Commagene, seated among the divine colossi at Nemrud Dag as the patroness of the land; a regional cult form of Greek Tyche.'),
 ('ENT_COMM_ANTIOCHUS_I_THEOS','PER_COMMAGENE','King of Commagene (r. c.70-31 BCE) who established and was deified within the royal pantheon; enthroned among the gods at Nemrud Dag and shown in dexiosis with each deity. A deified historical mortal.');
INSERT INTO entity_periods (entity_id,period_id,confidence,rationale,source_id,review_status)
INSERT INTO _r VALUES
 ('ENT_COMM_ZEUS_OROMASDES','member_of','ENT_COMM_PANTHEON','high','Zeus-Oromasdes is the supreme deity of the Commagenian dynastic pantheon at Nemrud Dag.'),
 ('ENT_COMM_APOLLO_MITHRAS_HELIOS_HERMES','member_of','ENT_COMM_PANTHEON','high','Apollo-Mithras-Helios-Hermes is one of the seated colossal deities of the Commagenian pantheon.'),
 ('ENT_COMM_ARTAGNES_HERACLES_ARES','member_of','ENT_COMM_PANTHEON','high','Artagnes-Heracles-Ares is one of the seated colossal deities of the Commagenian pantheon.'),
 ('ENT_COMM_TYCHE','member_of','ENT_COMM_PANTHEON','high','The Tyche of Commagene is seated among the divine colossi of the pantheon at Nemrud Dag.'),
 ('ENT_COMM_ANTIOCHUS_I_THEOS','member_of','ENT_COMM_PANTHEON','high','Antiochus I Theos enthroned himself as a deified king among the gods of his own dynastic pantheon.'),
 ('ENT_COMM_ZEUS_OROMASDES','equated_with','ENT_ZEUS','high','Ancient interpretatio: the theonym Zeus-Oromasdes explicitly equates the Commagenian supreme god with Greek Zeus.'),
 ('ENT_COMM_ZEUS_OROMASDES','equated_with','ENT_ZOR_AHURA_MAZDA','high','Ancient interpretatio: Oromasdes is the Hellenized form of Iranian Ahura Mazda, fused with Zeus in the Commagenian theonym.'),
 ('ENT_COMM_APOLLO_MITHRAS_HELIOS_HERMES','equated_with','ENT_APOLLO','high','Ancient interpretatio: the composite theonym explicitly identifies the Commagenian solar god with Greek Apollo.'),
 ('ENT_COMM_APOLLO_MITHRAS_HELIOS_HERMES','equated_with','ENT_ZOR_MITHRA','high','Ancient interpretatio: the Mithras element of the composite theonym derives from Iranian Mithra of the Zoroastrian tradition.'),
 ('ENT_COMM_APOLLO_MITHRAS_HELIOS_HERMES','syncretized_with','ENT_SYN_MITHRAS','medium','The Commagenian Apollo-Mithras-Helios-Hermes is a key early attestation of the Mithras whose cult later developed in the Roman world.'),
 ('ENT_COMM_APOLLO_MITHRAS_HELIOS_HERMES','equated_with','ENT_HELIOS','high','Ancient interpretatio: the Helios element of the composite theonym identifies the god with the Greek sun god.'),
 ('ENT_COMM_APOLLO_MITHRAS_HELIOS_HERMES','equated_with','ENT_HERMES','high','Ancient interpretatio: the Hermes element of the composite theonym identifies the god with the Greek messenger god.'),
 ('ENT_COMM_ARTAGNES_HERACLES_ARES','equated_with','ENT_ZOR_VERETHRAGNA','high','Ancient interpretatio: Artagnes is the Hellenized form of Iranian Verethragna, the Zoroastrian yazata of victory.'),
 ('ENT_COMM_ARTAGNES_HERACLES_ARES','equated_with','ENT_HERACLES','high','Ancient interpretatio: the composite theonym explicitly identifies the Commagenian warrior god with Greek Heracles.'),
 ('ENT_COMM_ARTAGNES_HERACLES_ARES','equated_with','ENT_ARES','high','Ancient interpretatio: the Ares element of the composite theonym identifies the god with the Greek war god.'),
 ('ENT_COMM_TYCHE','cult_form_of','ENT_TYCHE','high','The Tyche of Commagene is a regional civic/territorial cult form of the Greek goddess Tyche (Fortune).'),
 ('ENT_COMM_ANTIOCHUS_I_THEOS','associated_with','ENT_COMM_ZEUS_OROMASDES','medium','The Nemrud Dag dexiosis reliefs depict Antiochus I clasping the hand of Zeus-Oromasdes, asserting his divine legitimacy.'),
 ('ENT_COMM_ANTIOCHUS_I_THEOS','associated_with','ENT_COMM_ARTAGNES_HERACLES_ARES','medium','A Nemrud Dag dexiosis relief shows Antiochus I clasping the hand of Artagnes-Heracles-Ares.');
